import { spawn, type ChildProcess } from 'node:child_process'
import { createServer, type Server } from 'node:net'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import { loadWindowsSecurity } from '../../shared/windows-security-addon'

// This test reads only a PID generated by itself or by its own disposable
// Node child. No host enumeration, motor operation or process termination
// outside the original ChildProcess handle.
const windowsOnly = process.platform === 'win32' ? describe : describe.skip

const sleep = (ms: number) =>
  new Promise<void>((resolve) => setTimeout(resolve, ms))

async function waitUntil(check: () => boolean, limit = 8000): Promise<void> {
  const start = Date.now()
  while (!check()) {
    if (Date.now() - start > limit) throw new Error('GATE9C3C_TIMEOUT')
    await sleep(100)
  }
}

function native() {
  const loaded = loadWindowsSecurity()
  if ('error' in loaded) throw new Error('GATE9C3C_ADDON_UNAVAILABLE: ' + loaded.error)
  expect(loaded.addon.hasNativeExport('inspectManagedQaRecordedProcess')).toBe(true)
  return loaded.addon
}

async function ownListener(): Promise<{ server: Server; port: number }> {
  const server = createServer((socket) => socket.destroy())
  const port = await new Promise<number>((resolve, reject) => {
    server.once('error', reject)
    server.listen(0, '127.0.0.1', () => {
      server.off('error', reject)
      const addr = server.address()
      if (!addr || typeof addr === 'string') {
        reject(new Error('GATE9C3C_NO_EPHEMERAL_PORT'))
      } else {
        resolve(addr.port)
      }
    })
  })
  return { server, port }
}

function minimalEnv(): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = { ORCA_GATE9C3_TEST_ONLY: '1' }
  for (const key of ['SystemRoot', 'WINDIR', 'TEMP', 'TMP', 'Path', 'PATHEXT']) {
    if (process.env[key]) env[key] = process.env[key]
  }
  return env
}

async function disposableListener(): Promise<{
  child: ChildProcess
  pid: number
  port: number
}> {
  const fixture = path.resolve(process.cwd(), 'tests/fixtures/orca-gate9c3-tcp-owner.cjs')
  const child = spawn(process.execPath, [fixture], {
    cwd: process.cwd(),
    shell: false,
    windowsHide: true,
    env: minimalEnv(),
    stdio: ['ignore', 'pipe', 'pipe', 'ipc']
  })
  return new Promise((resolve, reject) => {
    let complete = false
    let stdout = ''
    let stderr = ''
    const deadline = setTimeout(() => {
      if (complete) return
      complete = true
      child.kill()
      reject(new Error('GATE9C3C_FIXTURE_START_TIMEOUT ' + stderr.slice(0, 400)))
    }, 8000)
    child.stderr?.on('data', (chunk: Buffer) => {
      stderr += chunk.toString('utf8')
    })
    child.stdout?.on('data', (chunk: Buffer) => {
      stdout += chunk.toString('utf8')
      const newline = stdout.indexOf('\n')
      if (complete || newline === -1) return
      complete = true
      clearTimeout(deadline)
      try {
        const report = JSON.parse(stdout.slice(0, newline)) as {
          pid: number
          port: number
        }
        if (child.pid !== report.pid || !Number.isInteger(report.port)) {
          throw new Error('GATE9C3C_INVALID_FIXTURE_REPORT')
        }
        resolve({ child, ...report })
      } catch (error) {
        child.kill()
        reject(error)
      }
    })
    child.once('error', (error) => {
      if (complete) return
      complete = true
      clearTimeout(deadline)
      reject(error)
    })
    child.once('exit', (code) => {
      if (complete) return
      complete = true
      clearTimeout(deadline)
      reject(new Error('GATE9C3C_FIXTURE_EXITED_EARLY ' + code + ': ' + stderr))
    })
  })
}

async function dispose(child: ChildProcess): Promise<void> {
  if (child.exitCode !== null || child.signalCode !== null) return
  const exit = new Promise<void>((resolve) => child.once('exit', () => resolve()))
  child.send?.('close')
  let timer: ReturnType<typeof setTimeout> | null = null
  try {
    await Promise.race([
      exit,
      new Promise<never>((_resolve, reject) => {
        timer = setTimeout(() => reject(new Error('GATE9C3C_FIXTURE_STOP_TIMEOUT')), 6000)
      })
    ])
  } finally {
    if (timer) clearTimeout(timer)
    // Only ever stop the ChildProcess we directly created.
    if (child.exitCode === null && child.signalCode === null) child.kill()
  }
}

windowsOnly('Gate 9B-C3-C: recorded process Win32 identity is read-only', () => {
  it('distinguishes the same living process from a recycled PID', async () => {
    const addon = native()
    const { server, port } = await ownListener()
    try {
      await waitUntil(() => addon.inspectManagedQaTcpListeners(port).status === 'LISTENER_PRESENT')
      const census = addon.inspectManagedQaTcpListeners(port)
      expect(census.status).toBe('LISTENER_PRESENT')
      if (census.status !== 'LISTENER_PRESENT') return
      const self = census.listeners.find((row) => row.pid === process.pid)
      expect(self?.creationTimeTicks).toMatch(/^[1-9][0-9]{11,19}$/)
      const ticks = self!.creationTimeTicks!
      const match = addon.inspectManagedQaRecordedProcess(process.pid, ticks)
      expect(match).toMatchObject({
        status: 'MATCH_RUNNING',
        pid: process.pid,
        actualCreationTimeTicks: ticks
      })
      expect(match.executablePath).toEqual(expect.any(String))
      const wrong = (BigInt(ticks) + 1n).toString()
      expect(addon.inspectManagedQaRecordedProcess(process.pid, wrong).status).toBe('PID_REUSED')
    } finally {
      await new Promise<void>((resolve) => server.close(() => resolve()))
    }
  }, 15000)

  it('does not adopt a synthetic owner that has exited', async () => {
    const addon = native()
    const fixture = await disposableListener()
    let stopped = false
    try {
      const census = addon.inspectManagedQaTcpListeners(fixture.port)
      expect(census.status).toBe('LISTENER_PRESENT')
      if (census.status !== 'LISTENER_PRESENT') return
      const candidate = census.listeners.find((row) => row.pid === fixture.pid)
      expect(candidate?.identityVerified).toBe(true)
      const ticks = candidate!.creationTimeTicks!
      expect(addon.inspectManagedQaRecordedProcess(fixture.pid, ticks).status)
        .toBe('MATCH_RUNNING')
      await dispose(fixture.child)
      stopped = true
      // Windows may retain an exited process handle briefly, and the PID
      // could theoretically be reused. Never interpret either as authority
      // to start a new motor.
      await waitUntil(() =>
        addon.inspectManagedQaRecordedProcess(fixture.pid, ticks).status !== 'MATCH_RUNNING'
      )
      expect(['NOT_RUNNING', 'MATCH_EXITED', 'PID_REUSED']).toContain(
        addon.inspectManagedQaRecordedProcess(fixture.pid, ticks).status
      )
    } finally {
      if (!stopped) await dispose(fixture.child)
    }
  }, 15000)

  it('rejects missing or malformed recorded PID and FILETIME', () => {
    const addon = native()
    for (const pid of [0, -2, 3.14, NaN, 4294967296]) {
      expect(() => addon.inspectManagedQaRecordedProcess(pid, '133776550123456789')).toThrow()
    }
    for (const ticks of ['', '0', '00133776550123456789', '1e17', 'not-verified']) {
      expect(() => addon.inspectManagedQaRecordedProcess(process.pid, ticks)).toThrow()
    }
  })
})
